// n8n Code Node - Find Available 1-Hour Calendar Slots (Business Hours: 10 AM - 6 PM)
// Input: Google Calendar events and filter dates
// Output: Array of available 1-hour time slots during business hours (Beirut time)

// Helper function to format a Date object into an ISO 8601-like string for Beirut time
// (YYYY-MM-DDTHH:mm:ss) without the time zone offset.
function toBeirutFormattedString(date) {
  const tz = 'Asia/Beirut';
  const options = {
    year: 'numeric',
    month: '2-digit',
    day: '2-digit',
    hour: '2-digit',
    minute: '2-digit',
    second: '2-digit',
    hour12: false,
    timeZone: tz
  };
  const parts = new Intl.DateTimeFormat('en-GB', options).formatToParts(date);

  const lookup = {};
  parts.forEach(p => {
    if (p.type !== 'literal') lookup[p.type] = p.value;
  });

  return `${lookup.year}-${lookup.month}-${lookup.day}T${lookup.hour}:${lookup.minute}:${lookup.second}`;
}


// Get input data - try different n8n access methods
let inputData;
try {
  inputData = $input.all();
} catch (e) {
  inputData = [$input.item];
}

// Debug
console.log('Raw input data:', JSON.stringify(inputData, null, 2));

let filterData = null;
let eventsData = [];

// Try to extract filter and events data safely
try {
  if (inputData && inputData[0] && inputData[0].data) {
    filterData = inputData[0].data[0];
    eventsData = inputData[0].data[1] ? inputData[0].data[1].data || [] : [];
  }
} catch (e) {
  console.log('Method 1 failed:', e.message);
}

if (!filterData) {
  try {
    if (inputData && inputData[0]) {
      if (inputData[0].filter_start) {
        filterData = inputData[0];
        eventsData = inputData[1] ? inputData[1] : [];
      } else if (inputData[0].json && inputData[0].json.data) {
        filterData = inputData[0].json.data[0];
        eventsData = inputData[0].json.data[1] ? inputData[0].json.data[1].data || [] : [];
      }
    }
  } catch (e) {
    console.log('Method 2 failed:', e.message);
  }
}

if (!filterData) {
  try {
    const firstInput = $input.first();
    if (firstInput && firstInput.data) {
      filterData = firstInput.data[0];
      eventsData = firstInput.data[1] ? firstInput.data[1].data || [] : [];
    }
  } catch (e) {
    console.log('Method 3 failed:', e.message);
  }
}

if (!filterData || !filterData.filter_start || !filterData.filter_end) {
  throw new Error('Could not extract filter_start and filter_end from input. Please check the input data structure.');
}

console.log('Successfully extracted filter data:', filterData);
console.log('Events count:', eventsData.length);

const filterStart = new Date(filterData.filter_start);

// Force filterEnd to end of December + 2 years
const filterEnd = new Date(filterStart);
filterEnd.setFullYear(filterEnd.getFullYear() + 2);
filterEnd.setMonth(11); // December (0-indexed)
filterEnd.setDate(31);
filterEnd.setHours(23, 59, 59, 999);

// Business hours configuration
const BUSINESS_START_HOUR = 10; // 10 AM
const BUSINESS_END_HOUR = 18; // 6 PM

// Function to check if a time slot is within business hours
function isWithinBusinessHours(startTime, endTime) {
  const startHour = startTime.getHours();
  const endHour = endTime.getHours();
  return startHour >= BUSINESS_START_HOUR && endHour <= BUSINESS_END_HOUR;
}

// Function to convert event times to Date objects (handles all-day vs timed events)
function parseEventTime(eventTime, isAllDay = false) {
  if (!eventTime) return null;
  if (isAllDay) {
    return new Date(eventTime + "T00:00:00+03:00"); // Beirut all-day
  }
  return new Date(eventTime);
}

// Normalize events
const existingEvents = eventsData
  .map(event => {
    const isAllDay = !!event.start.date;
    const start = parseEventTime(event.start.dateTime || event.start.date, isAllDay);
    const end = parseEventTime(event.end.dateTime || event.end.date, isAllDay);
    if (!start || !end || isNaN(start.getTime()) || isNaN(end.getTime())) {
      return null;
    }
    return {
      start,
      end,
      id: event.id,
      isAllDay
    };
  })
  .filter(e => e !== null);

existingEvents.sort((a, b) => a.start - b.start);

// Function to check overlap
function isOverlapping(start1, end1, start2, end2) {
  return start1 < end2 && start2 < end1;
}

// Generate available slots
function generateAvailableSlots(startDate, endDate, existingEvents) {
  const availableSlots = [];
  const slotDuration = 60 * 60 * 1000; // 1 hour
  let currentDate = new Date(startDate);
  currentDate.setHours(0, 0, 0, 0);

  while (currentDate < endDate) {
    if (currentDate.getDay() === 0) { // skip Sundays
      currentDate.setDate(currentDate.getDate() + 1);
      continue;
    }

    for (let hour = BUSINESS_START_HOUR; hour < BUSINESS_END_HOUR; hour++) {
      const currentSlotStart = new Date(currentDate);
      currentSlotStart.setHours(hour, 0, 0, 0);
      const currentSlotEnd = new Date(currentSlotStart.getTime() + slotDuration);

      if (currentSlotStart < startDate || currentSlotEnd > endDate) continue;

      let isAvailable = true;
      for (const event of existingEvents) {
        if (isOverlapping(currentSlotStart, currentSlotEnd, event.start, event.end)) {
          isAvailable = false;
          break;
        }
      }

      if (isAvailable) {
        availableSlots.push({
          start: toBeirutFormattedString(currentSlotStart),
          end: toBeirutFormattedString(currentSlotEnd),
          startFormatted: currentSlotStart.toLocaleString('en-US', {
            timeZone: 'Asia/Beirut',
            year: 'numeric',
            month: '2-digit',
            day: '2-digit',
            hour: '2-digit',
            minute: '2-digit',
            hour12: true
          }),
          endFormatted: currentSlotEnd.toLocaleString('en-US', {
            timeZone: 'Asia/Beirut',
            year: 'numeric',
            month: '2-digit',
            day: '2-digit',
            hour: '2-digit',
            minute: '2-digit',
            hour12: true
          }),
          duration: "1 hour",
          dayOfWeek: currentSlotStart.toLocaleDateString('en-US', {
            weekday: 'long',
            timeZone: 'Asia/Beirut'
          }),
          date: currentSlotStart.toLocaleDateString('en-US', {
            timeZone: 'Asia/Beirut'
          }),
          businessHour: `${hour}:00 - ${hour + 1}:00`
        });
      }
    }

    currentDate.setDate(currentDate.getDate() + 1);
  }

  return availableSlots;
}

const availableSlots = generateAvailableSlots(filterStart, filterEnd, existingEvents);

// Prepare output
const output = {
  summary: {
    totalAvailableSlots: availableSlots.length,
    businessHours: `${BUSINESS_START_HOUR}:00 - ${BUSINESS_END_HOUR}:00`,
    filterPeriod: {
      start: toBeirutFormattedString(filterStart),
      end: toBeirutFormattedString(filterEnd),
    },
    existingEventsCount: existingEvents.length
  },
  availableSlots: availableSlots,
  existingEvents: existingEvents.map(event => ({
    start: toBeirutFormattedString(event.start),
    end: toBeirutFormattedString(event.end),
    startFormatted: event.start.toLocaleString('en-US', {
      timeZone: 'Asia/Beirut',
      year: 'numeric',
      month: '2-digit',
      day: '2-digit',
      hour: '2-digit',
      minute: '2-digit',
      hour12: true
    }),
    endFormatted: event.end.toLocaleString('en-US', {
      timeZone: 'Asia/Beirut',
      year: 'numeric',
      month: '2-digit',
      day: '2-digit',
      hour: '2-digit',
      minute: '2-digit',
      hour12: true
    }),
    id: event.id,
    isAllDay: event.isAllDay
  }))
};

return [output];
